  "diagnosis": "The function `next_cursor(page)` fails when the page object does not contain a 'cursor' key, leading to a `KeyError`. The earliest causal failure is in the line where the code attempts to access `page[\"cursor\"]`.",
  "expected_effect": "The function should handle cases where 'cursor' is not present by returning `None` instead of causing a KeyError.",
  "schema_version": "exp002-diagnosis-update/v1",
  "updates": {
    "harness.py": "def next_cursor(page):\n    \"\"\"Return the next usable pagination cursor or None.\"\"\"\n    next_cursor_key = page.get(\"next\")\n    if next_cursor_key:\n        return next_cursor_key\n    return None\n"
  }
}

